 54	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
 55	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
 56	  clients.push(client);
 57	  const frames: Frame[] = [];
 58	  let connected: Frame = {type: ''};
 59	  for await (const raw of client) {
 60	    const frame = JSON.parse(String(raw)) as Frame;
 61	    if (frame.type === 'connected') {
 62	      connected = frame;
 63	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
 64	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
 65	      continue;
 66	    }
 67	    if (frame.type === 'pong') break;
 68	    frames.push(frame);
 69	  }
 70	  return {connected, frames};
 71	};
